pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }

    function testFuzz_property(uint256 deposit, bool recipientReverts) public {
        deposit = bound(deposit, 1, 1 ether);

        RevertingRecipient r = new RevertingRecipient(recipientReverts);

        vm.deal(address(this), deposit);
        (bool s, ) = address(c).call{value: deposit}("");
        require(s, "funding c failed");

        assert(address(c).balance == deposit);

        bool ok;
        try c.withdraw{value:0}() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!(ok == true && address(c).balance > 0));
    }
}

contract RevertingRecipient {
    bool public shouldRevert;
    constructor(bool _shouldRevert) payable { shouldRevert = _shouldRevert; }
    receive() external payable {
        if (shouldRevert) revert("revert on receive");
    }
    fallback() external payable {
        if (shouldRevert) revert("revert on fallback");
    }
}
